package agent

import (
	"context"
	"fmt"
	"time"
)

// Deps carries everything the loop needs, resolved and owned before the run
// starts. Nothing here is global mutable state.
type Deps struct {
	Provider   Provider
	Tools      Toolset
	Options    Options
	System     string
	Cwd        string
	MaxTurns   int        // bound on provider round-trips per user-turn (0 = default)
	Limits     ToolLimits // per-tool output/time bounds
	Summarizer Summarizer // optional; enables compaction
	CompactAt  int        // window token estimate that triggers compaction (0 = never)
	Unattended bool       // no human available to answer mid-run (oneshot/observe/sub-runs)
	Clock      func() time.Time
}

// DriverHooks let a frontend supply presentation and cancellation without
// duplicating the continuation loop. All fields are optional.
type DriverHooks struct {
	OnAssistantDelta func(string)
	OnToolCall       func(ToolCall)
	OnToolResult     func(ToolResult)
	OnStatus         func(AgentStatus)
	Cancelled        func() bool
}

// UserInput is one prompt entering a user-turn.
type UserInput struct {
	Text string
}

// Outcome summarizes a completed user-turn.
type Outcome struct {
	Turns   int
	Usage   Usage
	Stopped bool // true if the run hit MaxTurns with tool calls still pending
	Blocked bool // true if a tool ended the turn to wait for a human decision
}

const defaultMaxTurns = 50

// Run executes one user-turn: it appends the user input, then loops
// provider round-trips, dispatching tool calls, until the model stops
// requesting tools, a bound is hit, or the run is cancelled. It mutates log in
// place and returns when the turn settles.
func Run(ctx context.Context, log *Log, dep Deps, in UserInput, hooks DriverHooks) (Outcome, error) {
	clock := dep.Clock
	if clock == nil {
		clock = time.Now
	}
	maxTurns := dep.MaxTurns
	if maxTurns <= 0 {
		maxTurns = defaultMaxTurns
	}

	log.Append(Item{Kind: ItemUserText, Text: in.Text, Meta: ItemMeta{Time: clock()}})
	setStatus(hooks, StatusWorking)

	var out Outcome
	for turnNo := 0; turnNo < maxTurns; turnNo++ {
		if err := checkCancel(ctx, hooks); err != nil {
			setStatus(hooks, StatusIdle)
			return out, err
		}
		if err := maybeCompact(ctx, log, dep); err != nil {
			setStatus(hooks, StatusIdle)
			return out, err
		}

		req := BuildRequest(log, dep.System, dep.Tools.Specs())
		ch, err := dep.Provider.Stream(ctx, req, dep.Options)
		if err != nil {
			setStatus(hooks, StatusIdle)
			return out, fmt.Errorf("provider stream: %w", err)
		}

		turn := NewTurn()
		for ev := range ch {
			if ferr := turn.Feed(ev, hooks.OnAssistantDelta); ferr != nil {
				drain(ch)
				setStatus(hooks, StatusIdle)
				return out, ferr
			}
		}

		assistant, calls, usage, err := turn.Result()
		if err != nil {
			setStatus(hooks, StatusIdle)
			return out, fmt.Errorf("turn %d: %w", turnNo, err)
		}
		out.Turns++
		out.Usage.Add(usage)

		if assistant.Kind == ItemAssistantText {
			assistant.Meta = ItemMeta{Time: clock(), Usage: usage}
			log.Append(assistant)
		}

		if len(calls) == 0 {
			setStatus(hooks, StatusIdle)
			return out, nil
		}

		log.Append(Item{Kind: ItemTurnBoundary, Meta: ItemMeta{Time: clock()}})
		for _, call := range calls {
			if err := checkCancel(ctx, hooks); err != nil {
				setStatus(hooks, StatusIdle)
				return out, err
			}
			if dispatch(ctx, log, dep, call, hooks, clock) {
				out.Blocked = true
			}
		}
		if out.Blocked {
			break
		}
	}

	// Reached here either by hitting MaxTurns (Stopped) or by a tool ending the
	// turn to wait for a human (Blocked). Both mean "needs a human."
	if !out.Blocked {
		out.Stopped = true
	}
	setStatus(hooks, StatusBlocked)
	return out, nil
}

// dispatch runs one tool call and appends its call and result items. A tool
// failure is reported back to the model as an error result rather than
// aborting the whole run, which is what lets the model recover. It returns
// whether the tool asked to end the user-turn (ToolResult.EndTurn).
func dispatch(ctx context.Context, log *Log, dep Deps, call ToolCall, hooks DriverHooks, clock func() time.Time) bool {
	c := call
	log.Append(Item{Kind: ItemToolCall, Call: &c, Meta: ItemMeta{Time: clock()}})
	if hooks.OnToolCall != nil {
		hooks.OnToolCall(call)
	}

	res := runTool(ctx, dep, call)

	r := res
	log.Append(Item{Kind: ItemToolResult, Result: &r, Meta: ItemMeta{Time: clock()}})
	if hooks.OnToolResult != nil {
		hooks.OnToolResult(res)
	}
	return res.EndTurn
}

func runTool(ctx context.Context, dep Deps, call ToolCall) ToolResult {
	tool, ok := dep.Tools[call.Name]
	if !ok {
		return ToolResult{CallID: call.ID, Name: call.Name, IsError: true,
			Content: fmt.Sprintf("unknown tool %q", call.Name)}
	}
	env := ToolEnv{Cwd: dep.Cwd, Limits: dep.Limits, Unattended: dep.Unattended}
	res, err := tool.Run(ctx, call.Args, env)
	if err != nil {
		return ToolResult{CallID: call.ID, Name: call.Name, IsError: true, Content: err.Error()}
	}
	res.CallID = call.ID
	res.Name = call.Name
	return res
}

func maybeCompact(ctx context.Context, log *Log, dep Deps) error {
	if dep.Summarizer == nil || dep.CompactAt <= 0 {
		return nil
	}
	if EstimateTokens(log.Window()) < dep.CompactAt {
		return nil
	}
	return Compact(ctx, log, dep.Summarizer)
}

func checkCancel(ctx context.Context, hooks DriverHooks) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if hooks.Cancelled != nil && hooks.Cancelled() {
		return context.Canceled
	}
	return nil
}

func setStatus(hooks DriverHooks, s AgentStatus) {
	if hooks.OnStatus != nil {
		hooks.OnStatus(s)
	}
}

func drain(ch <-chan StreamEvent) {
	for range ch {
	}
}

package agent

import (
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// Turn folds the stream events of one provider round-trip into the assistant
// item and tool calls it produced. It is pure: borrowed events in, owned
// results out, no I/O and no goroutines. A malformed event sequence is a
// precondition violation and returns an error rather than being papered over.
type Turn struct {
	text  strings.Builder
	calls map[int]*callAccum
	order []int
	usage Usage
	done  bool
	err   error
}

type callAccum struct {
	id   string
	name string
	args strings.Builder
}

// NewTurn returns a fresh accumulator.
func NewTurn() *Turn {
	return &Turn{calls: make(map[int]*callAccum)}
}

// ErrTurnClosed is returned when Feed is called after the turn has finished.
var ErrTurnClosed = errors.New("agent: feed after turn done")

// Feed advances the turn by one event. onText, if non-nil, is called with each
// text fragment as it arrives so a driver can stream output.
func (t *Turn) Feed(ev StreamEvent, onText func(string)) error {
	if t.done {
		return ErrTurnClosed
	}
	switch ev.Kind {
	case EventTextDelta:
		t.text.WriteString(ev.Text)
		if onText != nil && ev.Text != "" {
			onText(ev.Text)
		}
	case EventToolCallStart:
		if ev.Call == nil {
			return errors.New("agent: tool-call-start without call")
		}
		if _, ok := t.calls[ev.Call.Index]; ok {
			return fmt.Errorf("agent: duplicate tool-call start at index %d", ev.Call.Index)
		}
		t.calls[ev.Call.Index] = &callAccum{id: ev.Call.ID, name: ev.Call.Name}
		t.order = append(t.order, ev.Call.Index)
	case EventToolCallArgsDelta:
		if ev.Call == nil {
			return errors.New("agent: tool-call-args without call")
		}
		acc, ok := t.calls[ev.Call.Index]
		if !ok {
			return fmt.Errorf("agent: args for unknown tool-call index %d", ev.Call.Index)
		}
		acc.args.WriteString(ev.Call.Args)
	case EventToolCallEnd:
		if ev.Call == nil {
			return errors.New("agent: tool-call-end without call")
		}
		if _, ok := t.calls[ev.Call.Index]; !ok {
			return fmt.Errorf("agent: end for unknown tool-call index %d", ev.Call.Index)
		}
	case EventUsage:
		if ev.Usage != nil {
			t.usage = *ev.Usage
		}
	case EventError:
		if ev.Err == nil {
			return errors.New("agent: error event without error")
		}
		t.err = ev.Err
		t.done = true
	case EventDone:
		t.done = true
	default:
		return fmt.Errorf("agent: unknown stream event kind %d", ev.Kind)
	}
	return nil
}

// Done reports whether the turn has ended.
func (t *Turn) Done() bool { return t.done }

// Result returns the assistant text item (if any), the completed tool calls in
// arrival order, and the turn's usage. It returns the stream error if one was
// received. Tool call arguments default to an empty JSON object when the model
// emitted none.
func (t *Turn) Result() (assistant Item, calls []ToolCall, usage Usage, err error) {
	if t.err != nil {
		return Item{}, nil, t.usage, t.err
	}
	text := t.text.String()
	if strings.TrimSpace(text) != "" {
		assistant = Item{Kind: ItemAssistantText, Text: text}
	}
	for _, idx := range t.order {
		acc := t.calls[idx]
		raw := acc.args.String()
		if strings.TrimSpace(raw) == "" {
			raw = "{}"
		}
		if !json.Valid([]byte(raw)) {
			return Item{}, nil, t.usage, fmt.Errorf("agent: tool %q produced invalid JSON arguments", acc.name)
		}
		calls = append(calls, ToolCall{ID: acc.id, Name: acc.name, Args: json.RawMessage(raw)})
	}
	return assistant, calls, t.usage, nil
}

// Package agent is the pure, provider-independent core of erg: the
// conversation item log, the turn state machine, and the continuation loop.
// It has no dependency on HTTP, terminals, sockets, or the wall clock except
// through interfaces its callers inject. Interfaces that the loop consumes
// (Provider, Tool) are declared here, at the consumer, so adapters depend on
// the core and never the reverse.
package agent

import (
	"context"
	"encoding/json"
	"time"
)

// StreamEventKind classifies a single event emitted by a provider stream.
type StreamEventKind int

const (
	EventTextDelta         StreamEventKind = iota // incremental assistant text
	EventToolCallStart                            // a tool call begins (Call has Index/ID/Name)
	EventToolCallArgsDelta                        // a fragment of a tool call's JSON arguments
	EventToolCallEnd                              // a tool call's arguments are complete
	EventUsage                                    // token accounting for the turn
	EventDone                                     // the provider finished this turn
	EventError                                    // the stream failed; Err is set
)

// ToolCallDelta carries the incremental pieces of a tool call as a provider
// streams it. Index identifies the call within one turn; ID and Name arrive
// with the start event, Args arrives in fragments.
type ToolCallDelta struct {
	Index int
	ID    string
	Name  string
	Args  string
}

// Usage is token accounting for one turn.
type Usage struct {
	InputTokens  int
	OutputTokens int
}

// Add accumulates usage across turns.
func (u *Usage) Add(o Usage) {
	u.InputTokens += o.InputTokens
	u.OutputTokens += o.OutputTokens
}

// StreamEvent is one provider-independent event. Adapters translate native
// wire events into these; the turn state machine folds them into items.
type StreamEvent struct {
	Kind  StreamEventKind
	Text  string
	Call  *ToolCallDelta
	Usage *Usage
	Err   error
}

// ToolCall is a completed request from the model to run a tool.
type ToolCall struct {
	ID   string
	Name string
	Args json.RawMessage
}

// ToolResult is the outcome of dispatching a ToolCall, fed back to the model.
type ToolResult struct {
	CallID  string
	Name    string
	Content string
	IsError bool
	// EndTurn asks the loop to stop the current user-turn after this result and
	// report the agent as blocked (needs a human decision). The `ask` tool sets
	// it; the loop stays generic and does not hardcode a tool name.
	EndTurn bool
}

// ToolSpec is the schema advertised to the model for one tool.
type ToolSpec struct {
	Name        string
	Description string
	Schema      json.RawMessage
}

// Request is the provider-independent model-visible context for one turn. It
// is built from the item log window; it is never assembled by slicing the raw
// log directly (see BuildRequest).
type Request struct {
	System string
	Items  []Item
	Tools  []ToolSpec
}

// Options selects model behavior for a turn.
type Options struct {
	Model  string
	Effort string
}

// ModelMeta is the resolved view of the active model, for display.
type ModelMeta struct {
	Name     string
	Provider string
}

// Provider is one model backend behind a native API family. Adapters own wire
// protocols and emit provider-independent StreamEvents; agent behavior must
// never branch on a native response shape.
type Provider interface {
	// Stream runs one turn, emitting events on the returned channel and
	// closing it when the turn ends. It must honor ctx cancellation.
	Stream(ctx context.Context, req Request, opts Options) (<-chan StreamEvent, error)
	// Model returns resolved capability metadata.
	Model() ModelMeta
}

// ToolEnv is the execution environment handed to a tool.
type ToolEnv struct {
	Cwd    string
	Limits ToolLimits
	// Unattended is true when no human is available to answer mid-run (one-shot,
	// observe reactions, sub-runs). Tools like ask use it to avoid dead-ends.
	Unattended bool
}

// ToolLimits bounds a single tool invocation.
type ToolLimits struct {
	Timeout time.Duration
}

// Tool is a single capability the model can invoke.
type Tool interface {
	Name() string
	Spec() ToolSpec
	Run(ctx context.Context, args json.RawMessage, env ToolEnv) (ToolResult, error)
}

// Toolset is the set of enabled tools, keyed by name.
type Toolset map[string]Tool

// Specs returns the advertised schema for every tool in the set.
func (t Toolset) Specs() []ToolSpec {
	specs := make([]ToolSpec, 0, len(t))
	for _, tool := range t {
		specs = append(specs, tool.Spec())
	}
	return specs
}

// AgentStatus is the semantic state erg reports to its runtime (see herdr).
type AgentStatus int

const (
	StatusIdle    AgentStatus = iota // awaiting input; observe watching
	StatusWorking                    // running a turn or a triggered reaction
	StatusBlocked                    // needs a human decision (ask tool, or hit max_turns)
	StatusDone                       // one-shot finished; observe watch terminated
)

func (s AgentStatus) String() string {
	switch s {
	case StatusIdle:
		return "idle"
	case StatusWorking:
		return "working"
	case StatusBlocked:
		return "blocked"
	case StatusDone:
		return "done"
	default:
		return "unknown"
	}
}

package agent_test

import (
	"context"
	"encoding/json"
	"errors"
	"testing"

	"github.com/emergingrobotics/erg/internal/agent"
	"github.com/emergingrobotics/erg/internal/provider/mock"
)

type echoTool struct{ name string }

func (e echoTool) Name() string { return e.name }
func (e echoTool) Spec() agent.ToolSpec {
	return agent.ToolSpec{Name: e.name, Description: "echo args"}
}
func (e echoTool) Run(_ context.Context, args json.RawMessage, _ agent.ToolEnv) (agent.ToolResult, error) {
	return agent.ToolResult{Content: string(args)}, nil
}

func collectStatus(dst *[]agent.AgentStatus) agent.DriverHooks {
	return agent.DriverHooks{OnStatus: func(s agent.AgentStatus) { *dst = append(*dst, s) }}
}

func lastAssistant(log *agent.Log) (agent.Item, bool) {
	items := log.Items()
	for i := len(items) - 1; i >= 0; i-- {
		if items[i].Kind == agent.ItemAssistantText {
			return items[i], true
		}
	}
	return agent.Item{}, false
}

func TestRunTextOnly(t *testing.T) {
	p := mock.New(mock.Turn{Text: "the answer is 42", Usage: agent.Usage{InputTokens: 5, OutputTokens: 4}})
	log := agent.NewLog()
	var status []agent.AgentStatus
	out, err := agent.Run(context.Background(), log, agent.Deps{Provider: p}, agent.UserInput{Text: "q"}, collectStatus(&status))
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if out.Turns != 1 {
		t.Fatalf("expected 1 turn, got %d", out.Turns)
	}
	if out.Usage.OutputTokens != 4 {
		t.Fatalf("usage not accumulated: %+v", out.Usage)
	}
	a, ok := lastAssistant(log)
	if !ok || a.Text != "the answer is 42" {
		t.Fatalf("bad assistant item: %+v", a)
	}
	if len(status) < 2 || status[0] != agent.StatusWorking || status[len(status)-1] != agent.StatusIdle {
		t.Fatalf("status should go working..idle, got %v", status)
	}
}

func TestRunToolLoop(t *testing.T) {
	p := mock.New(
		mock.Turn{Calls: []mock.Call{{ID: "c1", Name: "echo", Args: `{"x":1}`}}},
		mock.Turn{Text: "done"},
	)
	log := agent.NewLog()
	dep := agent.Deps{Provider: p, Tools: agent.Toolset{"echo": echoTool{"echo"}}}
	out, err := agent.Run(context.Background(), log, dep, agent.UserInput{Text: "go"}, agent.DriverHooks{})
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if out.Turns != 2 {
		t.Fatalf("expected 2 turns, got %d", out.Turns)
	}

	var sawCall, sawResult bool
	for _, it := range log.Items() {
		if it.Kind == agent.ItemToolCall && it.Call.Name == "echo" {
			sawCall = true
		}
		if it.Kind == agent.ItemToolResult && it.Result.Content == `{"x":1}` && !it.Result.IsError {
			sawResult = true
		}
	}
	if !sawCall || !sawResult {
		t.Fatalf("expected echo call and result; call=%v result=%v", sawCall, sawResult)
	}
	if a, _ := lastAssistant(log); a.Text != "done" {
		t.Fatalf("expected final 'done', got %q", a.Text)
	}
}

func TestRunUnknownToolReportsError(t *testing.T) {
	p := mock.New(
		mock.Turn{Calls: []mock.Call{{ID: "c1", Name: "missing", Args: `{}`}}},
		mock.Turn{Text: "recovered"},
	)
	log := agent.NewLog()
	_, err := agent.Run(context.Background(), log, agent.Deps{Provider: p}, agent.UserInput{Text: "go"}, agent.DriverHooks{})
	if err != nil {
		t.Fatalf("run should not abort on tool error: %v", err)
	}
	var errored bool
	for _, it := range log.Items() {
		if it.Kind == agent.ItemToolResult && it.Result.IsError {
			errored = true
		}
	}
	if !errored {
		t.Fatal("expected an error tool result fed back to the model")
	}
}

type endTurnTool struct{}

func (endTurnTool) Name() string         { return "ask" }
func (endTurnTool) Spec() agent.ToolSpec { return agent.ToolSpec{Name: "ask"} }
func (endTurnTool) Run(_ context.Context, _ json.RawMessage, _ agent.ToolEnv) (agent.ToolResult, error) {
	return agent.ToolResult{Content: "paused", EndTurn: true}, nil
}

func TestRunBlocksOnEndTurnTool(t *testing.T) {
	p := mock.New(mock.Turn{Calls: []mock.Call{{ID: "c1", Name: "ask", Args: `{"question":"ok?"}`}}})
	log := agent.NewLog()
	var status []agent.AgentStatus
	dep := agent.Deps{Provider: p, Tools: agent.Toolset{"ask": endTurnTool{}}}
	out, err := agent.Run(context.Background(), log, dep, agent.UserInput{Text: "go"}, collectStatus(&status))
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if !out.Blocked || out.Stopped {
		t.Fatalf("expected blocked (not stopped), got %+v", out)
	}
	if status[len(status)-1] != agent.StatusBlocked {
		t.Fatalf("expected final status blocked, got %v", status)
	}
}

func TestRunMaxTurnsReportsBlocked(t *testing.T) {
	p := &mock.Provider{Responder: func(agent.Request) mock.Turn {
		return mock.Turn{Calls: []mock.Call{{ID: "c", Name: "echo", Args: `{}`}}}
	}}
	log := agent.NewLog()
	var status []agent.AgentStatus
	dep := agent.Deps{Provider: p, Tools: agent.Toolset{"echo": echoTool{"echo"}}, MaxTurns: 2}
	out, err := agent.Run(context.Background(), log, dep, agent.UserInput{Text: "go"}, collectStatus(&status))
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if !out.Stopped || out.Blocked {
		t.Fatalf("expected stopped (not blocked), got %+v", out)
	}
	if status[len(status)-1] != agent.StatusBlocked {
		t.Fatalf("max_turns should report blocked, got %v", status)
	}
}

func TestRunHitsMaxTurns(t *testing.T) {
	// Always returns a tool call, so the loop can only stop on the bound.
	p := &mock.Provider{Responder: func(agent.Request) mock.Turn {
		return mock.Turn{Calls: []mock.Call{{ID: "c", Name: "echo", Args: `{}`}}}
	}}
	log := agent.NewLog()
	dep := agent.Deps{Provider: p, Tools: agent.Toolset{"echo": echoTool{"echo"}}, MaxTurns: 3}
	out, err := agent.Run(context.Background(), log, dep, agent.UserInput{Text: "go"}, agent.DriverHooks{})
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if !out.Stopped || out.Turns != 3 {
		t.Fatalf("expected stopped after 3 turns, got stopped=%v turns=%d", out.Stopped, out.Turns)
	}
}

func TestRunPropagatesProviderError(t *testing.T) {
	sentinel := errors.New("boom")
	p := mock.New(mock.Turn{Err: sentinel})
	log := agent.NewLog()
	_, err := agent.Run(context.Background(), log, agent.Deps{Provider: p}, agent.UserInput{Text: "q"}, agent.DriverHooks{})
	if !errors.Is(err, sentinel) {
		t.Fatalf("expected sentinel error, got %v", err)
	}
}

func TestRunCancellation(t *testing.T) {
	p := &mock.Provider{Responder: func(agent.Request) mock.Turn {
		return mock.Turn{Calls: []mock.Call{{ID: "c", Name: "echo", Args: `{}`}}}
	}}
	log := agent.NewLog()
	calls := 0
	hooks := agent.DriverHooks{Cancelled: func() bool { calls++; return calls > 1 }}
	dep := agent.Deps{Provider: p, Tools: agent.Toolset{"echo": echoTool{"echo"}}, MaxTurns: 100}
	_, err := agent.Run(context.Background(), log, dep, agent.UserInput{Text: "go"}, hooks)
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("expected cancellation, got %v", err)
	}
}

package agent

import (
	"errors"
	"strings"
	"testing"
)

func feed(t *testing.T, turn *Turn, evs ...StreamEvent) {
	t.Helper()
	for i, ev := range evs {
		if err := turn.Feed(ev, nil); err != nil {
			t.Fatalf("feed event %d: %v", i, err)
		}
	}
}

func TestTurnAccumulatesText(t *testing.T) {
	turn := NewTurn()
	var streamed strings.Builder
	turn.Feed(StreamEvent{Kind: EventTextDelta, Text: "Hello, "}, func(s string) { streamed.WriteString(s) })
	turn.Feed(StreamEvent{Kind: EventTextDelta, Text: "world"}, func(s string) { streamed.WriteString(s) })
	turn.Feed(StreamEvent{Kind: EventDone}, nil)

	if !turn.Done() {
		t.Fatal("turn should be done")
	}
	assistant, calls, _, err := turn.Result()
	if err != nil {
		t.Fatalf("result: %v", err)
	}
	if assistant.Kind != ItemAssistantText || assistant.Text != "Hello, world" {
		t.Fatalf("bad assistant item: %+v", assistant)
	}
	if len(calls) != 0 {
		t.Fatalf("expected no calls, got %d", len(calls))
	}
	if streamed.String() != "Hello, world" {
		t.Fatalf("onText got %q", streamed.String())
	}
}

func TestTurnAssemblesToolCalls(t *testing.T) {
	turn := NewTurn()
	feed(t, turn,
		StreamEvent{Kind: EventToolCallStart, Call: &ToolCallDelta{Index: 0, ID: "c1", Name: "read"}},
		StreamEvent{Kind: EventToolCallArgsDelta, Call: &ToolCallDelta{Index: 0, Args: `{"path":`}},
