// Package session provides resumable, plain-file persistence of the
// conversation log, keyed by working directory. A session is a header line
// plus one JSON line per item, so it is inspectable with ordinary tools and
// is exactly what a runtime's session-restore expects.
package session

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/emergingrobotics/erg/internal/agent"
)

// Meta is the session header, written as the first line of the file.
type Meta struct {
	ID        string `json:"id"`
	Cwd       string `json:"cwd"`
	Created   string `json:"created"`
	Updated   string `json:"updated"`
	Shape     string `json:"shape,omitempty"`
	Model     string `json:"model,omitempty"`
	Observe   bool   `json:"observe,omitempty"`
	Reactions int    `json:"reactions,omitempty"` // observe watch progress
}

// Store is a directory of session files.
type Store struct{ dir string }

// Open returns the session store, honoring ERG_SESSIONS then XDG config.
func Open() (*Store, error) {
	dir := os.Getenv("ERG_SESSIONS")
	if dir == "" {
		base, err := os.UserConfigDir()
		if err != nil {
			return nil, err
		}
		dir = filepath.Join(base, "erg", "sessions")
	}
	return &Store{dir: dir}, nil
}

// NewID returns a time-ordered, unique session id.
func NewID() string {
	return time.Now().UTC().Format("20060102T150405") + "-" + fmt.Sprintf("%04x", time.Now().UnixNano()&0xffff)
}

func (s *Store) path(id string) string { return filepath.Join(s.dir, id+".jsonl") }

// Save writes the header and every item to the session file, replacing it.
func (s *Store) Save(meta Meta, items []agent.Item) error {
	if err := os.MkdirAll(s.dir, 0o755); err != nil {
		return err
	}
	meta.Updated = time.Now().UTC().Format(time.RFC3339Nano)
	if meta.Created == "" {
		meta.Created = meta.Updated
	}
	tmp := s.path(meta.ID) + ".tmp"
	f, err := os.Create(tmp)
	if err != nil {
		return err
	}
	w := bufio.NewWriter(f)
	enc := json.NewEncoder(w)
	if err := enc.Encode(meta); err != nil {
		f.Close()
		return err
	}
	for _, it := range items {
		if err := enc.Encode(it); err != nil {
			f.Close()
			return err
		}
	}
	if err := w.Flush(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	return os.Rename(tmp, s.path(meta.ID))
}

// Load reads a session by id.
func (s *Store) Load(id string) (Meta, []agent.Item, error) {
	f, err := os.Open(s.path(id))
	if err != nil {
		return Meta{}, nil, err
	}
	defer f.Close()

	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 16*1024*1024)
	var meta Meta
	if !sc.Scan() {
		return Meta{}, nil, fmt.Errorf("session %s: empty file", id)
	}
	if err := json.Unmarshal(sc.Bytes(), &meta); err != nil {
		return Meta{}, nil, fmt.Errorf("session %s: bad header: %w", id, err)
	}
	var items []agent.Item
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		var it agent.Item
		if err := json.Unmarshal([]byte(line), &it); err != nil {
			return Meta{}, nil, fmt.Errorf("session %s: bad item: %w", id, err)
		}
		items = append(items, it)
	}
	return meta, items, sc.Err()
}

// List returns session metadata for cwd, newest first. An empty cwd lists all.
func (s *Store) List(cwd string) ([]Meta, error) {
	entries, err := os.ReadDir(s.dir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	var metas []Meta
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".jsonl") {
			continue
		}
		id := strings.TrimSuffix(e.Name(), ".jsonl")
		meta, _, err := s.Load(id)
		if err != nil {
			continue // skip unreadable sessions rather than failing the listing
		}
		if cwd != "" && meta.Cwd != cwd {
			continue
		}
		metas = append(metas, meta)
	}
	sort.Slice(metas, func(i, j int) bool { return metas[i].Updated > metas[j].Updated })
	return metas, nil
}

// Latest returns the id of the most recently updated session for cwd, or "".
func (s *Store) Latest(cwd string) (string, error) {
	metas, err := s.List(cwd)
	if err != nil || len(metas) == 0 {
		return "", err
	}
	return metas[0].ID, nil
}

