func TestLogWindowAndCompaction(t *testing.T) {
	log := NewLog()
	log.Append(Item{Kind: ItemUserText, Text: "one"})
	log.Append(Item{Kind: ItemAssistantText, Text: "two"})
	log.Append(Item{Kind: ItemUserText, Text: "three"})

	if log.Len() != 3 || len(log.Window()) != 3 {
		t.Fatalf("expected full window of 3, got len=%d window=%d", log.Len(), len(log.Window()))
	}

	sum := fixedSummarizer("SUMMARY")
	if err := Compact(context.Background(), log, sum); err != nil {
		t.Fatalf("compact: %v", err)
	}

	// Full log retains history plus the seed; window is only the seed.
	if log.Len() != 4 {
		t.Fatalf("expected 4 items after compaction, got %d", log.Len())
	}
	win := log.Window()
	if len(win) != 1 || win[0].Kind != ItemSummarySeed || win[0].Text != "SUMMARY" {
		t.Fatalf("window should be the summary seed, got %+v", win)
	}
	if log.Items()[0].Text != "one" {
		t.Fatal("history must be retained in the full log")
	}
}

func TestLogLoadPlacesWindowAtLastSeed(t *testing.T) {
	log := NewLog()
	log.Load([]Item{
		{Kind: ItemUserText, Text: "a"},
		{Kind: ItemSummarySeed, Text: "s1"},
		{Kind: ItemUserText, Text: "b"},
	})
	win := log.Window()
	if len(win) != 2 || win[0].Kind != ItemSummarySeed {
		t.Fatalf("window should start at the summary seed, got %+v", win)
	}
}

func TestBuildRequestCopiesWindow(t *testing.T) {
	log := NewLog()
	log.Append(Item{Kind: ItemUserText, Text: "hi"})
	req := BuildRequest(log, "SYS", []ToolSpec{{Name: "read"}})
	if req.System != "SYS" || len(req.Items) != 1 || len(req.Tools) != 1 {
		t.Fatalf("bad request: %+v", req)
	}
	// Mutating the returned slice must not affect the log.
	req.Items[0].Text = "mutated"
	if log.Items()[0].Text != "hi" {
		t.Fatal("BuildRequest must copy window items")
	}
}

type fixedSummarizer string

func (f fixedSummarizer) Summarize(_ context.Context, _ []Item) (string, error) {
	return string(f), nil
}

