// Package app wires the resolved configuration into a runnable agent: it
// builds the provider, toolset, herdr client, and session store, and hosts the
// three drivers (oneshot, interactive, observe). It is the only place that
// depends on every other package, keeping the leaf packages decoupled.
package app

import (
	"context"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/emergingrobotics/erg/internal/agent"
	"github.com/emergingrobotics/erg/internal/config"
	"github.com/emergingrobotics/erg/internal/herdr"
	"github.com/emergingrobotics/erg/internal/provider"
	"github.com/emergingrobotics/erg/internal/session"
	"github.com/emergingrobotics/erg/internal/terminal"
	"github.com/emergingrobotics/erg/internal/tool"
)

// App holds everything one run needs.
type App struct {
	cfg      *config.Config
	resolved config.Resolved
	deps     agent.Deps
	herdr    *herdr.Client
	sessions *session.Store
	cwd      string
	shape    string

	log   *agent.Log
	meta  session.Meta
	usage agent.Usage // accumulated across the session, for /usage
}

// Build assembles an App from config and the effective overrides.
func Build(ctx context.Context, cfg *config.Config, ov config.Overrides, cwd string) (*App, error) {
	resolved, err := config.Resolve(cfg, ov)
	if err != nil {
		return nil, err
	}

	prov, err := provider.Build(ctx, resolved.Provider, resolved.Model)
	if err != nil {
		return nil, err
	}

	sub := subRunner(cfg, cwd)
	tools, err := tool.Select(tool.Core(sub), resolved.Tools)
	if err != nil {
		return nil, err
	}

	sessions, err := session.Open()
	if err != nil {
		return nil, err
	}

	hc := herdr.New(herdr.Detect())
	shapeName := ov.Shape
	if shapeName == "" {
		shapeName = cfg.DefaultShape
	}
	hc.ReportMetadata(map[string]string{
		"shape":    orNone(shapeName),
		"model":    prov.Model().Name,
		"provider": prov.Model().Provider,
	})

	opts := agent.Options{Model: resolved.Model, Effort: resolved.Effort}
	return &App{
		cfg:      cfg,
		resolved: resolved,
		deps: agent.Deps{
			Provider:   prov,
			Tools:      tools,
			Options:    opts,
			System:     resolved.System,
			Cwd:        cwd,
			MaxTurns:   resolved.MaxTurns,
			Limits:     agent.ToolLimits{Timeout: 2 * time.Minute},
			Summarizer: agent.NewProviderSummarizer(prov, opts),
			CompactAt:  cfg.CompactAt,
			Clock:      time.Now,
		},
		herdr:    hc,
		sessions: sessions,
		cwd:      cwd,
		shape:    shapeName,
		log:      agent.NewLog(),
		meta:     session.Meta{ID: session.NewID(), Cwd: cwd, Shape: shapeName},
	}, nil
}

// Close releases resources held for the run. It relinquishes erg's herdr agent
// authority so the pane stops showing an agent once erg exits.
func (a *App) Close() {
	a.herdr.Release()
}

// Resume loads a prior session into the app by id.
func (a *App) Resume(id string) error {
	meta, items, err := a.sessions.Load(id)
	if err != nil {
		return err
	}
	a.log = agent.NewLog()
	a.log.Load(items)
	a.meta = meta
	return nil
}

// ResumeLatest loads the most recent session for the working directory, if any.
// It reports whether a session was found.
func (a *App) ResumeLatest() (bool, error) {
	id, err := a.sessions.Latest(a.cwd)
	if err != nil || id == "" {
		return false, err
	}
	return true, a.Resume(id)
}

// SessionID returns the current session id (for resume hints).
func (a *App) SessionID() string { return a.meta.ID }

// save persists the current log to the session file.
func (a *App) save() error {
	a.meta.Cwd = a.cwd
	a.meta.Shape = a.shape
	a.meta.Model = a.deps.Provider.Model().Name
	a.meta.Observe = a.resolved.Loop == config.LoopObserve
	return a.sessions.Save(a.meta, a.log.Items())
}

// Loop reports the resolved loop mode.
func (a *App) Loop() config.LoopMode { return a.resolved.Loop }

// summarizer builds a compaction summarizer backed by the active provider, so
// /compact works against whatever model this app is pointed at, local or cloud.
func (a *App) summarizer() agent.Summarizer {
	return agent.NewProviderSummarizer(a.deps.Provider, a.deps.Options)
}

// Observe returns the resolved observe config, or nil.
func (a *App) Observe() *config.ObserveConfig { return a.resolved.Observe }

// subRunner builds the task tool's sub-run executor: it resolves the named
// shape, builds a provider and (task-free) toolset for it, runs a bounded
// user-turn on a fresh log, and returns the final assistant text.
func subRunner(cfg *config.Config, cwd string) tool.SubRunner {
	return func(ctx context.Context, shape, prompt string) (string, error) {
		resolved, err := config.Resolve(cfg, config.Overrides{Shape: shape})
		if err != nil {
			return "", err
		}
		prov, err := provider.Build(ctx, resolved.Provider, resolved.Model)
		if err != nil {
			return "", err
		}
		tools, err := tool.Select(tool.Core(nil), resolved.Tools) // no nested task tool
		if err != nil {
			return "", err
		}
		dep := agent.Deps{
			Provider:   prov,
			Tools:      tools,
			Options:    agent.Options{Model: resolved.Model, Effort: resolved.Effort},
			System:     resolved.System,
			Cwd:        cwd,
			MaxTurns:   resolved.MaxTurns,
			Limits:     agent.ToolLimits{Timeout: 2 * time.Minute},
			Unattended: true, // a sub-run has no human to answer an ask
		}
		log := agent.NewLog()
		if _, err := agent.Run(ctx, log, dep, agent.UserInput{Text: prompt}, agent.DriverHooks{}); err != nil {
			return "", err
		}
		items := log.Items()
		for i := len(items) - 1; i >= 0; i-- {
			if items[i].Kind == agent.ItemAssistantText {
				return items[i].Text, nil
			}
		}
		return "", fmt.Errorf("sub-run produced no answer")
	}
}

func orNone(s string) string {
	if s == "" {
		return "default"
	}
	return s
}

// switchProvider switches to a different provider from the config.
// It rebuilds the provider and updates the app's deps.
func (a *App) switchProvider(ctx context.Context, out io.Writer, st terminal.Styler, name string) error {
	// Validate provider exists
	pc, ok := a.cfg.Providers[name]
	if !ok {
		return fmt.Errorf("unknown provider %q; use /provider to see available providers", name)
	}

	// Build the new provider
	newProv, err := provider.Build(ctx, pc, "")
	if err != nil {
		return fmt.Errorf("failed to build provider %q: %w", name, err)
	}

	oldProvider := a.deps.Provider.Model().Provider
	a.deps.Provider = newProv

	a.resetForRebuild(out, st)
	fmt.Fprintf(out, "switched from %s to %s (model %s)\n", oldProvider, newProv.Model().Provider, newProv.Model().Name)
	fmt.Fprintln(out, st.Dim("note: conversation cleared for the new provider"))
	return nil
}

// resetForRebuild clears the conversation into a fresh session, resets usage,
// republishes metadata, and redraws the header — shared by /provider and /shape
// so the two stay in sync.
func (a *App) resetForRebuild(out io.Writer, st terminal.Styler) {
	a.log = agent.NewLog()
	a.meta = session.Meta{ID: session.NewID(), Cwd: a.cwd, Shape: a.shape}
	a.usage = agent.Usage{} // the new session starts its own token tally
	m := a.deps.Provider.Model()
	a.herdr.ReportMetadata(map[string]string{
		"shape":    orNone(a.shape),
		"model":    m.Name,
		"provider": m.Provider,
	})
	if st.Color {
		fmt.Fprint(out, st.ClearScreen())
		fmt.Fprint(out, a.headerBox(st, terminal.Width()))
		fmt.Fprintln(out, st.Dim(footerHint))
	}
	if err := a.save(); err != nil {
		fmt.Fprintln(os.Stderr, "erg: warning: could not save session:", err)
	}
}

// showProvider displays the current, default, and configured providers.
func (a *App) showProvider(out io.Writer, st terminal.Styler) {
	cfg := a.cfg
	current := a.deps.Provider.Model()

	fmt.Fprintf(out, "Current provider: %s (%s)\n", current.Name, current.Provider)
	fmt.Fprintf(out, "Default provider: %s\n", cfg.DefaultProvider)
	fmt.Fprintln(out, "\nConfigured providers:")

	for name, pc := range cfg.Providers {
		active := ""
		if name == cfg.DefaultProvider {
			active = " (default)"
		}
		fmt.Fprintf(out, "  • %s%s\n", name, active)
		fmt.Fprintf(out, "    type: %s\n", pc.Type)
		if pc.Model != "" {
			fmt.Fprintf(out, "    model: %s\n", pc.Model)
		}
		if pc.BaseURL != "" {
			fmt.Fprintf(out, "    base_url: %s\n", pc.BaseURL)
		}
		fmt.Fprintf(out, "    params: %v\n", pc.Params)
	}
}

// switchShape re-resolves config for a different shape and rebuilds the running
// deps (provider, model, tools, system prompt) around it, resetting the
// conversation. The loop mode is fixed at launch, so a live switch keeps the
// current driver and only swaps the shape's "personality."
func (a *App) switchShape(ctx context.Context, out io.Writer, st terminal.Styler, name string) error {
	if _, ok := a.cfg.Shapes[name]; !ok {
		return fmt.Errorf("unknown shape %q; use /shape to see available shapes", name)
	}
	resolved, err := config.Resolve(a.cfg, config.Overrides{Shape: name})
	if err != nil {
		return err
	}
	prov, err := provider.Build(ctx, resolved.Provider, resolved.Model)
	if err != nil {
		return fmt.Errorf("build provider for shape %q: %w", name, err)
	}
	tools, err := tool.Select(tool.Core(subRunner(a.cfg, a.cwd)), resolved.Tools)
	if err != nil {
		return err
	}

	// The loop mode is fixed at launch; a live shape switch keeps the current
	// driver and only swaps the shape's provider/model/prompt/tools.
	resolved.Loop = a.resolved.Loop
	opts := agent.Options{Model: resolved.Model, Effort: resolved.Effort}
	a.resolved = resolved
	a.shape = name
	a.deps.Provider = prov
	a.deps.Tools = tools
	a.deps.Options = opts
	a.deps.System = resolved.System
	a.deps.MaxTurns = resolved.MaxTurns
	a.deps.Summarizer = agent.NewProviderSummarizer(prov, opts)

	a.resetForRebuild(out, st)
	fmt.Fprintf(out, "switched to shape %q (%s via %s)\n", name, prov.Model().Name, prov.Model().Provider)
	fmt.Fprintln(out, st.Dim("note: conversation cleared for the new shape"))
	return nil
}

// showShape lists the configured shapes, marking the current and default ones.
func (a *App) showShape(out io.Writer) {
	current := a.shape
	if current == "" {
		current = "(none)"
	}
	fmt.Fprintf(out, "Current shape: %s\n", current)
	if a.cfg.DefaultShape != "" {
		fmt.Fprintf(out, "Default shape: %s\n", a.cfg.DefaultShape)
	}
	fmt.Fprintln(out, "\nConfigured shapes:")
	if len(a.cfg.Shapes) == 0 {
		fmt.Fprintln(out, "  (none defined)")
		return
	}
	for name, s := range a.cfg.Shapes {
		mark := ""
		if name == a.shape {
			mark = " *"
		} else if name == a.cfg.DefaultShape {
			mark = " (default)"
		}
		fmt.Fprintf(out, "  • %s%s  [%s]\n", name, mark, s.Loop)
	}
}
